const order: ArchetypeId[] = ['noeud', 'barque', 'roseau', 'mycelium', 'graine', 'cage', 'phare', 'riviere', 'cercles', 'fissure', 'plume', 'pierres'];
export const crossingKey = (a: ArchetypeId, b: ArchetypeId) => [a, b].sort((x, y) => order.indexOf(x) - order.indexOf(y)).join('|');

const invitations = [
  'L’image reste ouverte. Votre désaccord peut aussi y trouver une place.',
  'Une association peut rester provisoire et déplacer déjà quelque chose.',
  'Ce qui vient à l’un ne vient pas forcément à l’autre. C’est un espace pour penser.',
  'Quel détail de la situation prend maintenant une autre couleur ?',
  'Laissons cette image rencontrer la situation, sans les faire coïncider.',
  'Un autre angle n’efface pas le précédent. Il agrandit le champ.',
  'Quelle pensée encore incomplète cherche une place dans notre échange ?',
  'La métaphore ne conclut pas. Elle nous rend une question.',
];

export interface ResonanceInspiration {
  id: string;
  seed: number;
  lensKey: string;
  title: string;
  symbols: Archetype[];
  paragraphs: string[];
  question: string;
  invitation: string;
}

export function seededRandom(seed: number) {
  let value = seed >>> 0;
  return () => {
    value += 0x6D2B79F5;
    let t = Math.imul(value ^ value >>> 15, 1 | value);
    t ^= t + Math.imul(t ^ t >>> 7, 61 | t);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}

// Après le pont imagé, une phrase située dans l’expérience de l’équipe enrichit le croisement.
const situatedSentence = (body: string) => {
  const sentences = body.match(/[^.!?]+[.!?](?:\s|$)/g) ?? [body];
  const situated = sentences.map(sentence => sentence.trim()).filter(sentence =>
    /nous|notre|nos |équipe|staff|profession|collectif|réunion|collègue|récit|travail/i.test(sentence)
    && !/^(Elle|Elles|Il|Ils|Cela|Cette image|La métaphore)\b/.test(sentence));
  return situated.find(sentence => /équipe|staff|profession|collectif|réunion|collègue/i.test(sentence))
    ?? situated[0] ?? sentences[0].trim();
};

/** La mémoire est celle de la visite seulement ; aucune donnée clinique n’entre dans ce moteur. */
export function makeInspiration(symbols: Archetype[], recent: string[], seed: number): ResonanceInspiration {
  if (!symbols.length || symbols.length > 3) throw new Error('Choisir un à trois symboles.');
  const random = seededRandom(seed);
  const candidates = symbols.flatMap(symbol => perspectives[symbol.id].map((lens, i) => ({ symbol, lens, key: `${symbol.id}-${i}` })));
  const unseen = candidates.filter(item => !recent.includes(item.key));
  const available = unseen.length ? unseen : candidates.filter(item => !recent.slice(-3).includes(item.key));
  const picked = available[Math.floor(random() * available.length)];
  const others = symbols.filter(symbol => symbol.id !== picked.symbol.id);
  const paragraphs = [picked.lens.body];
  let question = picked.lens.questions[Math.floor(random() * 2)];
  for (const [i, other] of others.entries()) {
    const bridge = crossings[crossingKey(picked.symbol.id, other.id)];
    const echoes = perspectives[other.id];
    const echo = echoes[Math.floor(random() * echoes.length)];
    paragraphs.push(`${bridge.body} ${situatedSentence(echo.body)}`);
    if (i === 0 && random() > .45) question = bridge.question;
  }
  return {
    id: `${seed}-${picked.key}`, seed, lensKey: picked.key, title: picked.lens.title,
    symbols: [...symbols], paragraphs, question,
    invitation: invitations[Math.floor(random() * invitations.length)],
  };
}
